const listGames = `-- name: ListGames :many
SELECT id, white_user_id, black_user_id,
       fen, history, history_san,
       engine_white, engine_black, white_think_time, black_think_time,
       time_control, rated, status, result,
       created_at, updated_at, start_fen, is_public, assessments, imported
FROM games
WHERE (white_user_id = $1::BIGINT OR black_user_id = $1::BIGINT)
  AND updated_at < COALESCE($2::TIMESTAMPTZ, NOW())
ORDER BY updated_at DESC, id DESC
LIMIT $3::INT
`

type ListGamesParams struct {
	Column1 int64     `json:"column_1"`
	Column2 time.Time `json:"column_2"`
	Column3 int32     `json:"column_3"`
}

type ListGamesRow struct {
	ID             string        `json:"id"`
	WhiteUserID    sql.NullInt64 `json:"white_user_id"`
	BlackUserID    sql.NullInt64 `json:"black_user_id"`
	Fen            string        `json:"fen"`
	History        string        `json:"history"`
	HistorySan     string        `json:"history_san"`
	EngineWhite    bool          `json:"engine_white"`
	EngineBlack    bool          `json:"engine_black"`
	WhiteThinkTime int32         `json:"white_think_time"`
	BlackThinkTime int32         `json:"black_think_time"`
	TimeControl    string        `json:"time_control"`
	Rated          bool          `json:"rated"`
	Status         string        `json:"status"`
	Result         string        `json:"result"`
	CreatedAt      time.Time     `json:"created_at"`
	UpdatedAt      time.Time     `json:"updated_at"`
	StartFen       string        `json:"start_fen"`
	IsPublic       bool          `json:"is_public"`
	Assessments    string        `json:"assessments"`
	Imported       bool          `json:"imported"`
}

// Games where the user is on either side. Cursor-paginated: callers pass
// $2 as "newer than" (typically the last seen updated_at) or NOW() for the
// first page, and $3 as the page size. NULL/zero $2 falls back to NOW().
// The (updated_at, id) tie-break keeps pagination stable when multiple
// rows share an updated_at.
func (q *Queries) ListGames(ctx context.Context, arg ListGamesParams) ([]ListGamesRow, error) {
	rows, err := q.db.QueryContext(ctx, listGames, arg.Column1, arg.Column2, arg.Column3)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListGamesRow{}
	for rows.Next() {
		var i ListGamesRow
		if err := rows.Scan(
			&i.ID,
			&i.WhiteUserID,
			&i.BlackUserID,
			&i.Fen,
			&i.History,
			&i.HistorySan,
			&i.EngineWhite,
			&i.EngineBlack,
			&i.WhiteThinkTime,
			&i.BlackThinkTime,
			&i.TimeControl,
			&i.Rated,
			&i.Status,
			&i.Result,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.StartFen,
			&i.IsPublic,
			&i.Assessments,
			&i.Imported,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

